package edu.pbs.hub.config; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.web.servlet.config.annotation.*; import java.nio.file.*;
@Configuration public class AppConfig implements WebMvcConfigurer { @Value("${app.upload-dir}") String uploadDir; @Override public void addCorsMappings(CorsRegistry r){r.addMapping("/api/**").allowedOriginPatterns("*").allowedMethods("GET","POST","PUT","DELETE","OPTIONS").allowedHeaders("*");} @Override public void addResourceHandlers(ResourceHandlerRegistry r){try{Path p=Paths.get(uploadDir).toAbsolutePath();Files.createDirectories(p);r.addResourceHandler("/files/**").addResourceLocations(p.toUri().toString());}catch(Exception e){throw new RuntimeException(e);}} }
